\label{fractionalSI}
Assume that $p(\cdot)\in\mathcal{P}^{\log}(\mathbb{R}^d)$ satisfies
\(
1<p^- \le p^+<\infty
\),
and let $s\in(0,1)$ be such that $s<\frac{d}{p^+}$. Then there exists
$C=C(d,p,s)>0$ such that
\[
\|u\|_{L^{p^{*}(\cdot)}(\mathbb{R}^{d})}
\leq
C\,\|\nabla^{s}u\|_{L^{p(\cdot)}(\mathbb{R}^{d};\mathbb{R}^d)}
\]
for all $u\in {X}^{s,p(\cdot)}(\mathbb{R}^{d})$, where for $x\in \mathbb{R}^d$,
\begin{equation}\label{def-p-ast}
\frac{1}{p^{*}(x)}:=\frac{1}{p(x)}-\frac{s}{d}.
\end{equation}

\label{thm:SteinWeissVariable}
Fix $0<s<1$. Let $p(\cdot),q(\cdot)\in\mathcal{P}^{\log}(\mathbb{R}^d)$ with
$1<p^-\le p^+<\infty$ and $1<q^-\le q^+<\infty$. Assume
$p(x)\le q(x)$ for every  $x\in\mathbb{R}^d$.
Let  $a\in \mathbb{R}$ satisfy
\begin{equation}\label{eq:SW1}
-\frac{d}{q^+}<a\le 0,
\end{equation}
and suppose  that
\begin{equation}\label{eq:SW2}
\frac{1}{p(x)}-\frac{1}{q(x)}
=
\frac{s}{d}
+
\frac{a}{d}, \qquad x\in \mathbb{R}^d.
\end{equation}
Then, for all
$u\in  X^{s,p(\cdot)}(\mathbb{R}^d)$, there holds
\[
\bigl\||\cdot|^{\,a} u\bigr\|_{L^{q(\cdot)}(\mathbb{R}^d)}
\le
C
\bigl\|( \nabla^su)\bigr\|_{L^{p(\cdot)}(\mathbb{R}^d;\mathbb{R}^d)}.
\]
